import numpy as np
from forward import forward

np.random.seed(42)
x1 = np.random.randn(10)
x2 = np.random.randn(10)

def g(t):
    return forward((1-t)*x1 + t*x2)

def find_kinks(t_a, t_b, depth=0):
    g_a, g_b = g(t_a), g(t_b)
    t_m = (t_a + t_b) / 2
    g_m = g(t_m)

    expected_m = (g_a + g_b) / 2
    is_nonlinear = abs(g_m - expected_m) > 1e-6

    if is_nonlinear:
        if t_b - t_a < 1e-6:
            return [(t_a, t_b)]
        return find_kinks(t_a, t_m, depth+1) + find_kinks(t_m, t_b, depth+1)
    else:
        t_q1 = (t_a + t_m) / 2
        t_q2 = (t_m + t_b) / 2
        g_q1, g_q2 = g(t_q1), g(t_q2)
        q1_nl = abs(g_q1 - (g_a + g_m)/2) > 1e-6
        q2_nl = abs(g_q2 - (g_m + g_b)/2) > 1e-6
        if q1_nl or q2_nl:
            res = []
            if q1_nl or abs(g_m - expected_m) > 1e-6:
                res += find_kinks(t_a, t_m, depth+1)
            if q2_nl or abs(g_m - expected_m) > 1e-6:
                res += find_kinks(t_m, t_b, depth+1)
            return res
        return []

kinks = find_kinks(0.0, 1.0)
print('Count:', len(kinks))
for k in kinks:
    print(k)
